const Home = () => {
  const [age, setAge] = useState("");
  const [occupation, setOccupation] = useState("");
  const [tobacco, setTobacco] = useState("");
  const [coverage, setCoverage] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (age < 18) {
      setError("Age must be above 18");
      return;
    }
    if (!occupation || !tobacco || !coverage) {
      setError("All fields are required");
      return;
    }
    setError("");
    setLoading(true);



    try {


      setLoading(false);
      navigate("/chat", {
        state: { age, coverage, tobacco, occupation },
      });
    } catch (error) {
      console.error("Error submitting the form", error);
      setLoading(false);
    }
  };

  return (
    <Container>
      <FormWrapper>
        <Title>Enter your details</Title>
        <Form onSubmit={handleSubmit}>
          <FormGroup>
            <Label>
              <FaUser style={{ marginRight: "10px" }} /> Age:
            </Label>
            <Input
              type="number"
              value={age}
              onChange={(e) => setAge(e.target.value)}
            />
          </FormGroup>
          <FormGroup>
            <Label>
              <FaBriefcase style={{ marginRight: "10px" }} /> Occupation:
            </Label>
            <Select
              value={occupation}
              onChange={(e) => setOccupation(e.target.value)}
            >
              <option value="">Select</option>
              <option value="salaried">Salaried</option>
              <option value="self-employed">Self Employed</option>
            </Select>
          </FormGroup>
          <FormGroup>
            <Label>
              <FaSmoking style={{ marginRight: "10px" }} /> Tobacco Use:
            </Label>
            <Select
              value={tobacco}
              onChange={(e) => setTobacco(e.target.value)}
            >
              <option value="">Select</option>
              <option value="yes">Yes</option>
              <option value="no">No</option>
            </Select>
          </FormGroup>
          <FormGroup>
            <Label>
              <FaShieldAlt style={{ marginRight: "10px" }} /> Coverage:
            </Label>
            <Select
              value={coverage}
              onChange={(e) => setCoverage(e.target.value)}
            >
              <option value="">Select</option>
              <option value="10000000">1 Cr</option>
              <option value="15000000">1.5 Cr</option>
            </Select>
          </FormGroup>
          {error && <Error>{error}</Error>}
          <Button type="submit">{loading ? <Loader /> : "Submit"}</Button>
        </Form>
      </FormWrapper>
    </Container>
  );
};

const ChatBot = () => {
  const location = useLocation();
  const { age, occupation, tobacco, coverage, prompt } = location.state || {};
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [response, setResponse] = useState("");

  const handleSend = async () => {
    if (input.trim()) {
      setMessages([...messages, { text: input, user: true }]);

      const formData = {
        age,
        coverage_amt: coverage,
        tobacco,
        occupation,
        prompt: input,
        message: messages
      };
      const res = await axios.post("http://localhost:5000/res", formData, {
        headers: {
          "Content-Type": "application/json",
        },
      });
      console.log(messages)
      console.log(`response ${res.data.response}`)
      setInput("");
      setResponse(res.data.response);
      console.log(response)
      console.log(`object ${res}`);
      // Simulate bot response
      setTimeout(() => {
        setMessages((prevMessages) => [
          ...prevMessages,
          { text: `Bot Answer:${res.data.response}`, user: false },
        ]);
      }, 500);
    }
  };
  return (
    <ChatContainer>
      <ChatWrapper>
        <Title>Chat with our Bot</Title>
        <MessageContainer>
          {messages.map((msg, index) => (
            <Message key={index} user={msg.user}>
              <p>{msg.text}</p>
            </Message>
          ))}
        </MessageContainer>
        <InputContainer>
          <ChatInput
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Type a message..."
          />
          <ChatButton onClick={handleSend}>
            <FaPaperPlane size={18} />
          </ChatButton>
        </InputContainer>
      </ChatWrapper>
    </ChatContainer>
  );
};

const App = () => {
  return (
    <Routes>
      <Route path="/" element={<Home />} />
      <Route path="/chat" element={<ChatBot />} />
    </Routes>
  );
};

export default App;
